"use strict";exports.id=282,exports.ids=[282],exports.modules={10282:(a,b,c)=>{c.d(b,{th:()=>d,CY:()=>f,Kr:()=>i,$t:()=>h,eF:()=>g});let d=[{number:101,slug:"101",track:"advanced",programs:["Medical Assisting","Patient Care Technician"],title:"Medication & Treatment Documentation",unit:{number:6,title:"Advanced Topics"},sessions:"—",sessionsNote:{note:"The Instructor's Guide supplies no session count for the optional additional topics. Confirm whether these are timetabled, offered as enrichment, or used only if the calendar allows."},goals:["documentation","grammar-sentence"],spiralsFrom:[3,4],essentialQuestion:"Why must numbers, times, names, and details be documented with extreme accuracy?",concepts:["Accuracy as a safety property, not a tidiness one","Medication safety — the categories of error documentation can prevent","Reading labels and orders exactly as written","Numbers and units: a misplaced decimal is a tenfold error","Timing — when something was given is as important as what","Never guessing and never altering information after the fact"],grammar:[{heading:"Precision",points:["Numbers: write them so they cannot be misread","Capitalization of drug names and proper nouns","Abbreviations, and the ones that must never be used","Punctuation that changes meaning in a dosage","Commonly confused words in clinical writing"]}],wordListNumber:10,practice:[{kind:"grammar-drill",title:"Which entry is correct?",instructions:"Every option here is something that has appeared in a real record somewhere. Only one is safe.",items:[{id:"adv-a-1",prompt:"Which dosage is written safely?",principle:"A trailing zero after a decimal point is a known cause of tenfold overdose — 1.0 mg is read as 10 mg when the point is faint. Write 1 mg. Conversely, always use a leading zero: .5 mg is read as 5 mg; write 0.5 mg.",choices:[{text:"1.0 mg",correct:!1,rationale:"The trailing zero is dangerous. If the decimal point is faint or smudged this reads as 10 mg. Write 1 mg."},{text:"1 mg",correct:!0,rationale:"Correct. No trailing zero, no ambiguity, nothing that can be misread as a larger dose."},{text:".5 mg",correct:!1,rationale:"Missing the leading zero. A faint decimal point makes this read as 5 mg — a tenfold error. Write 0.5 mg."},{text:"1.0mg",correct:!1,rationale:"Trailing zero and no space before the unit, which makes 'mg' easy to misread as part of the number."}]},{id:"adv-a-2",prompt:"Which abbreviation should never be used?",principle:"Several abbreviations appear on the Institute for Safe Medication Practices' do-not-use list because they have a documented history of being misread with serious consequences.",choices:[{text:"mg for milligram",correct:!1,rationale:"Standard and unambiguous."},{text:"U for units",correct:!0,rationale:"Correct — this one is on the do-not-use list. A handwritten 'U' is read as a zero, turning 4U into 40 units. Write 'units'."},{text:"mL for milliliter",correct:!1,rationale:"Standard and unambiguous."},{text:"kg for kilogram",correct:!1,rationale:"Standard and unambiguous."}]},{id:"adv-a-3",prompt:"Which entry documents the time correctly?",principle:"Timing is often the most consequential detail in a medication record. Ambiguous time formats create gaps nobody can reconstruct later.",choices:[{text:"Given this morning.",correct:!1,rationale:"Unusable. 'This morning' could be a five-hour window, and the next dose is calculated from it."},{text:"Given at 0930.",correct:!0,rationale:"Correct. A specific time in an unambiguous 24-hour format."},{text:"Given at 9:30.",correct:!1,rationale:"Missing a.m. or p.m. In a 12-hour format that is a twelve-hour ambiguity."},{text:"Given before lunch.",correct:!1,rationale:"Relative to an event that happens at different times for different patients."}]},{id:"adv-a-4",prompt:"You realize an entry you made an hour ago has the wrong time. What do you do?",principle:"Records are corrected, never rewritten. Altering an entry so the original cannot be seen looks identical to concealment, whatever the intention.",choices:[{text:"Erase it and write the correct time",correct:!1,rationale:"Destroys the audit trail. In a paper record, erasure is itself a finding."},{text:"Use the correction process: mark it as an error, enter the correct information, and sign and date the correction",correct:!0,rationale:"Correct. The original stays visible, the correction is attributed, and anyone reading it later can see exactly what happened."},{text:"Leave it — an hour is not a significant difference",correct:!1,rationale:"The next dose may be calculated from that time. An hour can matter a great deal."},{text:"Ask a colleague to change it under their login",correct:!1,rationale:"Using another person's credentials is a serious violation on its own, quite apart from the falsification."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:10}],product:{label:"Simulated medication / treatment documentation record",description:"Complete a simulated medication or treatment documentation record. Every number, unit, and time must be written so it cannot be misread. Use no abbreviation from the do-not-use list."},reflection:["Read every number you wrote as though the decimal point were smudged. Does any of them become a different dose?","Could someone reconstruct exactly when each thing happened?","Is there any abbreviation here you would not want a tired colleague to interpret at 3am?"]},{number:102,slug:"102",track:"advanced",title:"HIPAA, Confidentiality & Ethical Writing",unit:{number:6,title:"Advanced Topics"},sessions:"—",sessionsNote:{note:"No session count is supplied for the optional additional topics. Confirm whether this is timetabled."},goals:["documentation","professional-writing","patient-centered"],spiralsFrom:[3,7],essentialQuestion:"What should I communicate, to whom, and how much information is appropriate?",concepts:["The minimum necessary principle — disclose what the purpose requires and no more","Confidentiality in writing, including in messages you consider informal","Appropriate audience: who actually needs to know this?","Professional boundaries in written communication","Public versus private communication, and how easily the line moves","Digital communication risks — forwarding, screenshots, and shared screens"],grammar:[{heading:"Clarity and precision",points:["Vague pronouns that leave the reader guessing who is meant","Ambiguous wording that could describe two different situations","Pronoun–noun agreement","Revising unclear sentences until only one reading is possible"]}],wordListNumber:11,practice:[{kind:"sorter",title:"Who needs to know?",instructions:"For each disclosure, decide whether it meets the minimum necessary standard.",bins:[{id:"ok",label:"Appropriate",hint:"The purpose requires it"},{id:"no",label:"Too much",hint:"More than the purpose requires"}],items:[{id:"adv-b-s1",text:"Sending records for one date of service to a specialist who requested them for that visit.",bin:"ok",feedback:"Limited to the purpose and the dates in question. This is the standard working correctly."},{id:"adv-b-s2",text:"Sending the complete chart because it is quicker than pulling the relevant pages.",bin:"no",feedback:"Convenience is not a purpose. Everything beyond what was requested is an unnecessary disclosure."},{id:"adv-b-s3",text:"Telling a colleague on the care team the patient's diagnosis so they can prepare the room appropriately.",bin:"ok",feedback:"A treatment purpose, disclosed to someone on the care team who needs it."},{id:"adv-b-s4",text:"Mentioning in the break room that a patient you both know came in today.",bin:"no",feedback:"Confirming that someone received care here is itself protected information, and a break room is not a private space."},{id:"adv-b-s5",text:"Answering a spouse's phone question about the visit, with no authorization on file.",bin:"no",feedback:"Marriage does not confer a right to another adult's health information. Confirming the visit happened already discloses too much."},{id:"adv-b-s6",text:"Including the diagnosis code on a claim submitted to the patient's insurer.",bin:"ok",feedback:"A payment purpose, which is a permitted disclosure. The claim carries what payment requires."}]},{kind:"rewrite",title:"Rewrite the unsafe message",instructions:"Each of these was sent. Rewrite so it does the job without the exposure.",items:[{id:"adv-b-r1",before:"Team — heads up that Maria Alvarez from the front desk's sister is coming in this afternoon for the thing we talked about. Be discreet!",problem:"Names the patient, identifies her by her relationship to a staff member, hints at the condition, and broadcasts it to a group. 'Be discreet' does not undo any of that.",model:"Team — we have a patient this afternoon who has asked for extra privacy. Please use the side room and avoid using names in the corridor. Details are in the chart for those directly involved in her care.",rubric:["Contains no name and no identifying relationship","Contains no hint of the condition","Says what staff should actually do differently","Points those who need details to the record rather than the message"]},{id:"adv-b-r2",before:"She said she'd been having those symptoms since the thing last year and she thinks it might be related to it.",problem:"Every noun has been replaced by a pronoun or 'thing'. A reader cannot tell what symptoms, what event, or what she thinks is related.",model:"Patient reports the joint pain has been present since her surgery in March 2025, and states, “I think it started after the operation.”",rubric:["Every pronoun has one clear referent","'Thing' and similar placeholders are replaced with the actual noun","The patient's own view is quoted rather than paraphrased","Only one reading of the sentence is possible"]}]},{kind:"word-bank",title:"Words to spell",listNumber:11}],product:{label:"Confidentiality incident / case response",description:"Analyze a confidentiality scenario and produce an appropriate written response: what happened, who needed to know, what should have been disclosed instead, and what you would do now."},reflection:["For each disclosure in your response, name the purpose it served.","Would the patient be comfortable reading what you wrote about them?","Is there anything here that identifies the patient indirectly?"]},{number:103,slug:"103",track:"advanced",programs:["Medical Billing"],title:"Insurance & Billing Communication",unit:{number:6,title:"Advanced Topics"},sessions:"—",sessionsNote:{note:"No session count is supplied for the optional additional topics. Confirm whether this is timetabled."},goals:["patient-centered","professional-writing","grammar-sentence"],spiralsFrom:[6,7],essentialQuestion:"How can I explain an administrative or billing issue clearly without creating confusion or sounding dismissive?",concepts:["Patient-friendly financial language","Avoiding jargon: deductible, coinsurance, and allowed amount all need translating","Accuracy — a wrong number in a billing message erodes trust immediately","Professional tone when the news is unwelcome","Communicating what the patient should do next, specifically"],grammar:[{heading:"Commonly confused words and precision",points:["affect versus effect","their, there, and they're","its versus it's","your versus you're","then versus than"]}],wordListNumber:12,practice:[{kind:"matcher",title:"Translate the billing jargon",instructions:"Match each term to plain language, then practise explaining it to a patient who is worried about money.",pairs:[{id:"adv-c-m1",term:"deductible",plain:"what you pay before the plan starts paying",explanation:"Your plan has a set amount you pay yourself each year before it begins covering costs. Once you have paid that amount, your plan starts sharing the cost with you."},{id:"adv-c-m2",term:"coinsurance",plain:"your percentage share of the cost",explanation:"After your deductible is met, you pay a percentage of the cost and your plan pays the rest. For you that share is 20 percent."},{id:"adv-c-m3",term:"allowed amount",plain:"the price your plan has agreed with us",explanation:"We and your insurance company agreed on a set price for this visit. That agreed price is what your share is calculated from — not the amount on our original bill."},{id:"adv-c-m4",term:"prior authorization",plain:"advance approval from your insurance",explanation:"Your insurance needs to approve this service before you have it. We send the request, and we will let you know as soon as they respond."},{id:"adv-c-m5",term:"out-of-network",plain:"a provider your plan has no agreement with",explanation:"This provider does not have a contract with your insurance company, so your plan covers less of the cost than it would elsewhere."}]},{kind:"grammar-drill",title:"Choose the correct word",instructions:"The confusable pairs that appear most in billing correspondence.",items:[{id:"adv-c-g1",prompt:"Which sentence is correct?",principle:"'Affect' is almost always the verb; 'effect' is almost always the noun. The change affects your bill; the change had an effect on your bill.",choices:[{text:"The change in your plan will effect your out-of-pocket cost.",correct:!1,rationale:"Needs the verb 'affect'."},{text:"The change in your plan will affect your out-of-pocket cost.",correct:!0,rationale:"Correct. 'Affect' is the verb — the change acts on the cost."},{text:"The affect of the change is a higher out-of-pocket cost.",correct:!1,rationale:"Needs the noun 'effect'."},{text:"The change will have an affect on your cost.",correct:!1,rationale:"After 'an', you need the noun 'effect'."}]},{id:"adv-c-g2",prompt:"Which sentence uses 'its' and 'it's' correctly?",principle:"'It's' is always 'it is' or 'it has'. 'Its' shows possession. If you cannot substitute 'it is', use 'its'.",choices:[{text:"Its important to know that you're plan changed it's terms.",correct:!1,rationale:"All three are wrong: It's, your, its."},{text:"It's important to know that your plan changed its terms.",correct:!0,rationale:"Correct. 'It's' expands to 'it is'; 'your' is possessive; 'its' is possessive."},{text:"It's important to know that you're plan changed it's terms.",correct:!1,rationale:"The first is right, but 'you're' and 'it's' are both wrong here."},{text:"Its important to know that your plan changed its terms.",correct:!1,rationale:"The first should be 'It's' — it expands to 'It is important'."}]},{id:"adv-c-g3",prompt:"A patient's claim was denied. Which message is professional without being dismissive?",principle:"When the news is unwelcome, lead with what you will do rather than with what the patient cannot have.",choices:[{text:"Your claim was denied. You will need to contact your insurance company.",correct:!1,rationale:"Accurate and cold. It hands the patient a problem and a phone number."},{text:"Unfortunately there is nothing we can do about this.",correct:!1,rationale:"Almost never true, and it closes the conversation before the patient understands what happened."},{text:"Your insurance did not cover this visit, and we are appealing that decision on your behalf. You do not need to do anything right now — we will call you by Friday with an update. If you have questions before then, call us at 555-0134.",correct:!0,rationale:"Correct. States what happened in plain language, says what is being done, tells the patient what they need to do (nothing), and gives a date."},{text:"Per your plan's terms, the service was adjudicated as non-covered pursuant to the benefit exclusions applicable to your policy year.",correct:!1,rationale:"Every word is jargon. A worried patient reads this twice and still does not know what to do."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:12}],product:{label:"Patient billing communication",description:"Write a professional communication explaining an insurance or billing issue to a patient. Translate every piece of jargon, state the numbers accurately, say what you are doing about it, and say what the patient should do next."},reflection:["Would a patient with no insurance knowledge understand what happened?","Did you say what you are doing, or only what went wrong?","Are all your numbers correct? Check them twice — a wrong figure here costs trust immediately."]},{number:104,slug:"104",track:"advanced",title:"Difficult Conversations & Professional Tone",unit:{number:6,title:"Advanced Topics"},sessions:"—",sessionsNote:{note:"No session count is supplied for the optional additional topics. Confirm whether this is timetabled."},goals:["professional-writing","patient-centered"],spiralsFrom:[7,9],essentialQuestion:"How can I communicate professionally when the patient or coworker is upset?",concepts:["Tone under pressure, in writing where you cannot soften it with your voice","De-escalation — acknowledging the feeling before addressing the facts","Empathy without overpromising: 'I understand' does not mean 'I will fix it'","Respectful language when you are being blamed","Boundaries: what you can offer and what you cannot","Professional responses to complaints"],grammar:[{heading:"Word choice",points:["Connotation — words that mean nearly the same thing and land very differently","Polite requests versus commands","Modal verbs: could, would, may, and how they soften without hedging","Positive versus negative framing of the same fact","Avoiding judgmental language when you are frustrated"]}],wordListNumber:13,practice:[{kind:"tone",title:"Tone under pressure",instructions:"Each of these is a reply to an upset patient or coworker. Place it, then rewrite the ones that miss.",samples:[{id:"adv-d-t1",text:"As I already explained in my previous message, the policy has not changed and there is nothing further I can do.",band:0,feedback:"Blunt. 'As I already explained' tells the reader they were not listening, and the reply closes every door at once.",professional:"I know this is frustrating, and I am sorry the answer has not changed. The policy does not allow an exception here, but I can put you in touch with our patient advocate, who may have options I do not."},{id:"adv-d-t2",text:"Received. Will look into it.",band:1,feedback:"Abrupt. It is not rude exactly, but to someone already upset it reads as indifference. Two more sentences would change how it lands entirely.",professional:"Thank you for letting me know — I can see why that would be frustrating. I am looking into it now and will get back to you by the end of the day, even if I only have a partial answer."},{id:"adv-d-t3",text:"I am sorry you waited so long today — an hour is a long time and you were not told why. Here is what happened, and here is what I can do about the rescheduling.",band:2,feedback:"Professional. Acknowledges the specific complaint, does not over-apologize or make excuses, and moves straight to what can be done."},{id:"adv-d-t4",text:"I am so incredibly sorry, this is entirely our fault and completely unacceptable, and I promise you this will never happen again and I will personally make sure everything is fixed for you.",band:3,feedback:"Over-soft, and it promises things you cannot deliver. Accepting blame on behalf of the practice and guaranteeing a future outcome both create problems, and the intensity can read as insincere.",professional:"I am sorry about the wait — that was longer than it should have been. I have passed it to our practice manager, and I can rebook you at a time that works better if that would help."}]},{kind:"grammar-drill",title:"Word choice under pressure",instructions:"Connotation, modals, and framing.",items:[{id:"adv-d-g1",prompt:"Which phrasing makes a request rather than issuing a command?",principle:"Modal verbs — could, would, may — soften a request without making it vague. The reader still knows exactly what is being asked.",choices:[{text:"Send me the file.",correct:!1,rationale:"An imperative. Fine in instructions, brusque between colleagues under tension."},{text:"Could you send me the file by Tuesday?",correct:!0,rationale:"Correct. The modal makes it a request, and the deadline keeps it specific."},{text:"I need that file.",correct:!1,rationale:"States your need and leaves the reader to infer the request."},{text:"It would be great if maybe someone could possibly send the file at some point.",correct:!1,rationale:"So softened that nobody knows they are being asked, or by when."}]},{id:"adv-d-g2",prompt:"Which is the better framing of the same fact: the appointment cannot happen before Thursday.",principle:"Positive framing says what is possible. Negative framing says what is not, and leaves the reader with nowhere to go.",choices:[{text:"We cannot see you before Thursday.",correct:!1,rationale:"True, and it gives the patient a refusal rather than an option."},{text:"The earliest we can see you is Thursday at 10:00. Shall I hold that for you?",correct:!0,rationale:"Correct. Same fact, stated as an available option, with a next step attached."},{text:"Unfortunately nothing is available until Thursday, sorry.",correct:!1,rationale:"Two apology words around the same refusal. It softens the tone without helping."},{text:"Thursday is the only day.",correct:!1,rationale:"Abrupt, and it omits the time and the offer to book it."}]},{id:"adv-d-g3",prompt:"A patient writes an angry message blaming you personally for a billing error you did not make. What is the best opening line?",principle:"Acknowledge the feeling before the facts. Defending yourself first, however justified, escalates.",choices:[{text:"That was not my error.",correct:!1,rationale:"True and escalating. It makes the exchange about responsibility rather than about fixing the bill."},{text:"I am sorry this happened — an unexpected bill is stressful, and I want to get it sorted for you.",correct:!0,rationale:"Correct. Acknowledges the impact without accepting blame, and moves to the resolution. 'I am sorry this happened' is not an admission of fault."},{text:"Please calm down and I will look at it.",correct:!1,rationale:"Telling an upset person to calm down reliably has the opposite effect."},{text:"Per our policy, billing inquiries must be directed to the billing department.",correct:!1,rationale:"Procedurally correct and completely unresponsive to a person who is upset."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:13}],product:{label:"Professional response to a difficult scenario",description:"Write a professional response to an upset patient or coworker. Acknowledge the feeling, state the facts accurately, say what you can do and what you cannot, and give a next step. Do not overpromise."},reflection:["Read your first sentence. Does it acknowledge, or defend?","Did you promise anything you cannot personally deliver?","Would you be comfortable if your supervisor read this?"]}],e=[{number:1,slug:"1",title:"Course Introduction: Building Our Class Community",unit:{number:1,title:"Foundations of Professional Healthcare Communication"},sessions:"1",goals:["professional-writing"],intro:["Welcome to Writing and Communication for Healthcare Professionals. This session is about getting to know the course, getting comfortable with your classmates and instructors, and beginning to think about why communication and writing matter in healthcare.","Do not worry about getting everything right today. Your first writing sample is a starting point, not a test."],essentialQuestion:{note:"The Instructor's Guide does not state an Essential Question for the orientation session. The 'Questions to think about' below are used in its place on the Brightspace Week 1 page. Confirm whether one should be added for consistency with Topics 2–10."},concepts:["Describe the purpose of the course and why strong writing matters in healthcare","Identify the types of writing used in healthcare workplaces","Explain how practice, feedback, and revision build a stronger writer","Locate course materials and assignments in Brightspace","Complete a short writing sample as a baseline"],grammar:{note:"The Instructor's Guide assigns no Grammar Focus to the orientation session; explicit grammar instruction begins with the Topic 2 diagnostic. Confirm whether this section should stay empty or preview the diagnostic."},wordListNumber:1,practice:[{kind:"word-bank",title:"Words to know",listNumber:1}],product:{note:"The guide lists a professional self-introduction writing warm-up for this session rather than a cumulative workplace product. The warm-up prompt appears under 'Think about' below. Confirm whether Topic 1 should carry a formal workplace product."},reflection:["Why does good writing matter in healthcare?","What makes communication clear, accurate, and professional?","What does it mean to become a better writer?","How can feedback and revision help me improve?","Writing warm-up: Think about a time when someone communicated something to you clearly — or when a message was confusing. What made the communication effective or ineffective? Write honestly and in your own words. This is not a grammar test."],beforeYouLeave:["Completed the Brightspace orientation activities","Participated in the class community activity","Completed the Writing Warm-Up in Amplify","Reviewed the Writing Portfolio information"],closingLine:"You are not expected to be a perfect writer when you begin this course. You are here to become a better one."},{number:2,slug:"2",title:"Foundations: Clear and Professional Communication",unit:{number:1,title:"Foundations of Professional Healthcare Communication"},sessions:"1–2",goals:["grammar-sentence","professional-writing","patient-centered"],essentialQuestion:"Why does clear writing matter in healthcare?",concepts:["Communication is a patient-safety issue, not only a matter of politeness","What makes healthcare writing effective","Clarity, correctness, and professionalism are three different things — a message can be correct and still unclear","Audience and purpose: who is reading this, and what do they need to do after reading it?","Introduction to the Communication Check, the five criteria you will use all term"],grammar:[{heading:"Diagnostic focus — a non-graded baseline",points:["Parts of speech and what each one does in a sentence","Subject and predicate","Complete sentences","Subject–verb agreement","Capitalization","Basic punctuation","Fragments","Run-ons","Pronoun clarity"]}],wordListNumber:2,practice:[{kind:"grammar-drill",title:"Grammar diagnostic",instructions:"A baseline, not a grade. Answer honestly — the point is to find out what to work on, and every option explains itself.",items:[{id:"t2-sva-1",prompt:"Choose the sentence with correct subject–verb agreement.",principle:"The verb agrees with the subject, not with a noun that happens to sit closest to it. Find the real subject first — here it is 'box', not 'gloves'.",choices:[{text:"The box of gloves are stored in the supply room.",correct:!1,rationale:"The subject is 'box', which is singular, so it takes 'is'. 'Gloves' is inside a prepositional phrase and cannot be the subject."},{text:"The box of gloves is stored in the supply room.",correct:!0,rationale:"Correct. The singular subject 'box' takes the singular verb 'is', regardless of the plural noun in between."},{text:"The box of gloves were stored in the supply room.",correct:!1,rationale:"'Were' is plural and past tense. The singular subject 'box' needs 'is' or 'was'."},{text:"The boxes of gloves is stored in the supply room.",correct:!1,rationale:"Here the subject 'boxes' is plural, so it needs 'are'. The subject and verb do not match."}]},{id:"t2-frag-1",prompt:"Which of these is a sentence fragment?",principle:"A complete sentence needs a subject and a verb and must express a complete thought. A group of words beginning with 'because', 'after', or 'while' needs a main clause attached to it.",choices:[{text:"Because the patient arrived without her insurance card.",correct:!0,rationale:"Correct. This has a subject and verb but begins with 'because', so it is a dependent clause left on its own — the reader is still waiting for what happened."},{text:"The patient arrived without her insurance card.",correct:!1,rationale:"This is complete: subject 'patient', verb 'arrived', and a finished thought."},{text:"She returned the next morning with it.",correct:!1,rationale:"Complete — subject 'she', verb 'returned', finished thought."},{text:"Verify insurance at check-in.",correct:!1,rationale:"This is an imperative sentence. The subject 'you' is understood rather than written, which is correct for an instruction."}]},{id:"t2-runon-1",prompt:"Which sentence is a run-on?",principle:"Two complete sentences cannot be joined by a comma alone. Fix a comma splice with a period, a semicolon, or a comma plus a joining word such as 'and', 'but', or 'so'.",choices:[{text:"The waiting room was full, the front desk called for help.",correct:!0,rationale:"Correct. Two complete sentences joined by only a comma — a comma splice. Use a period, a semicolon, or add 'so'."},{text:"The waiting room was full, so the front desk called for help.",correct:!1,rationale:"Correct as written. A comma plus the joining word 'so' properly connects two complete sentences."},{text:"The waiting room was full. The front desk called for help.",correct:!1,rationale:"Two correct sentences, separated by a period."},{text:"Because the waiting room was full, the front desk called for help.",correct:!1,rationale:"Correct. A dependent clause followed by a comma and a main clause."}]},{id:"t2-pronoun-1",prompt:"Which sentence has a pronoun that is unclear about who it refers to?",principle:"A pronoun must point to exactly one noun. When two people of the same gender appear in a sentence, repeat the name rather than using 'she' or 'he'.",choices:[{text:"When the nurse spoke with the patient, she seemed concerned.",correct:!0,rationale:"Correct. 'She' could mean the nurse or the patient. In documentation this ambiguity can change the meaning of the record — name the person."},{text:"When the nurse spoke with the patient, the patient seemed concerned.",correct:!1,rationale:"Clear. Repeating the noun removes any doubt about who was concerned."},{text:"The patient said she had not eaten since midnight.",correct:!1,rationale:"Clear. Only one person appears, so 'she' has one possible referent."},{text:"Dr. Reyes reviewed the chart before he entered the room.",correct:!1,rationale:"Clear. Only one person is named, so 'he' is unambiguous."}]},{id:"t2-caps-1",prompt:"Which sentence is capitalized correctly?",principle:"Capitalize proper nouns — specific names of people, places, departments, days, and months. Do not capitalize a general job title or a common noun just because it feels important.",choices:[{text:"The Patient will see the Doctor on tuesday in Radiology.",correct:!1,rationale:"'Patient' and 'Doctor' are common nouns here and should be lowercase, and 'Tuesday' needs a capital."},{text:"The patient will see the doctor on Tuesday in Radiology.",correct:!0,rationale:"Correct. Common nouns stay lowercase, the day of the week is capitalized, and Radiology as a named department is capitalized."},{text:"the patient will see the doctor on Tuesday in radiology.",correct:!1,rationale:"The first word of a sentence must be capitalized, and the named department Radiology should be too."},{text:"The Patient will see Dr. Okafor on tuesday in radiology.",correct:!1,rationale:"'Dr. Okafor' is correct, but 'Patient' should be lowercase and 'Tuesday' needs a capital."}]},{id:"t2-prof-1",prompt:"A coworker needs the updated supply list. Which message is appropriate for the workplace?",principle:"Professional does not mean stiff. It means clear about what you need, specific about when, and respectful of the reader's time.",choices:[{text:"hey can u send me that list asap?? need it",correct:!1,rationale:"Missing capitalization and punctuation, abbreviations, and no specificity about which list or when it is needed."},{text:"Send the supply list.",correct:!1,rationale:"Grammatically correct but abrupt, and it gives no deadline or context. Correct is not the same as professional."},{text:"Hi Marcus — could you send me the updated supply list before Thursday's order? Thank you.",correct:!0,rationale:"Correct. It greets the reader, names exactly what is needed, gives a deadline and a reason, and stays brief."},{text:"I was wondering if at some point when you have a moment you might possibly be able to look into sending over that list we discussed.",correct:!1,rationale:"Polite but wordy and vague. The reader still does not know which list or when it is due."}]},{id:"t2-clarity-1",prompt:"Which version of this instruction is clearest for a patient?",principle:"Clarity means the reader knows exactly what to do. Replace vague timing with specific timing, and jargon with plain words.",choices:[{text:"Take the medication as directed with adequate hydration.",correct:!1,rationale:"'As directed' and 'adequate hydration' assume the patient already knows. Neither tells them what to actually do."},{text:"Take one tablet with a full glass of water every morning with breakfast.",correct:!0,rationale:"Correct. It states how much, with what, how often, and when — nothing is left for the patient to guess."},{text:"Administer one tablet PO QAM with food.",correct:!1,rationale:"This is written for a clinician, not a patient. Abbreviations like PO and QAM belong in the record, not in patient instructions."},{text:"Take your medication regularly and stay hydrated.",correct:!1,rationale:"'Regularly' could mean anything. The patient cannot follow this without more information."}]},{id:"t2-subject-1",prompt:"What is the complete subject of this sentence? “The new front-desk assistant verified the patient's insurance before the appointment.”",principle:"The complete subject is who or what the sentence is about, together with the words describing it. Find the verb first, then ask who or what did it.",choices:[{text:"assistant",correct:!1,rationale:"That is the simple subject. The complete subject also includes the words describing it."},{text:"The new front-desk assistant",correct:!0,rationale:"Correct. The verb is 'verified'; who verified? The new front-desk assistant — including all its describing words."},{text:"the patient's insurance",correct:!1,rationale:"That is the object — what was verified, not who did the verifying."},{text:"before the appointment",correct:!1,rationale:"That is a prepositional phrase telling you when. It cannot be the subject."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:2}],product:{label:"Professional patient or staff communication",description:"Write a short professional communication from the scenario below. It must apply this topic's grammar and spelling, use a professional tone, stay clear, and keep to objective language. Aim for four to six sentences — brevity is part of the skill.",scenario:"A patient has called the office asking to move an appointment that is scheduled for Thursday. The next opening with her provider is the following Tuesday at 10:00 a.m. She also asked whether she still needs to fast beforehand; the answer is yes, for eight hours. Write the message she will receive."},reflection:["Read your draft out loud. Where did you stumble? That is usually where the reader will too.","Did you tell the reader what to do next, or only give them information?","Could someone outside healthcare understand every word you used?"],beforeYouLeave:["Completed the grammar diagnostic","Reviewed Word Bank List 2, including the confusable pairs","Drafted the patient or staff communication","Checked your draft against all five Communication Check criteria"]},{number:3,slug:"3",title:"Writing About Patients: Objective Documentation",unit:{number:2,title:"Clinical Documentation"},sessions:"2",goals:["documentation","grammar-sentence","summarizing"],spiralsFrom:[2],essentialQuestion:"How can I document what happened without adding my opinions or assumptions?",concepts:["Why documentation must be precise and evidence-based — the record may become part of the professional and legal record","Objective information (what you measured, saw, or heard) versus subjective information (what the patient reported)","Objective language versus judgmental language","Facts versus interpretations","Observations versus assumptions — you can document that a patient winced; you cannot document that they were in severe pain"],grammar:[{heading:"Nouns, verbs, and pronouns",points:["Nouns name a person, place, thing, or idea","Subject versus object: who is doing the action, and who receives it","Pronoun forms, and keeping the reference unmistakable"]},{heading:"Types of verbs",points:["Action verbs: what someone did — walked, reported, refused","Linking verbs and forms of 'to be': connect a subject to a description","Active voice through subject–verb placement: 'The patient refused the medication' rather than 'The medication was refused'"]}],wordListNumber:3,practice:[{kind:"sorter",title:"Fact or opinion?",instructions:"Sort each statement. If it could not be measured, quoted, or directly observed, it is not objective.",bins:[{id:"objective",label:"Objective",hint:"Measured, observed, or quoted"},{id:"subjective",label:"Opinion or assumption",hint:"Interpreted or judged"}],items:[{id:"t3-s1",text:"Blood pressure 148/92, right arm, seated.",bin:"objective",feedback:"A measurement with the conditions recorded. Anyone could verify it."},{id:"t3-s2",text:"Patient seems anxious about the procedure.",bin:"subjective",feedback:"'Seems' is the tell. You are interpreting a mental state you cannot observe directly."},{id:"t3-s3",text:"Patient states, “I have not eaten since yesterday morning.”",bin:"objective",feedback:"A direct quotation of what the patient reported. The quotation marks make clear it is their account, not your conclusion."},{id:"t3-s4",text:"Patient is being difficult about the blood draw.",bin:"subjective",feedback:"'Difficult' is a judgment about the person. Document the behavior instead: what did they say or do?"},{id:"t3-s5",text:"Patient withdrew their arm twice during the attempted venipuncture.",bin:"objective",feedback:"An observable action, counted. This is what 'difficult' should have been."},{id:"t3-s6",text:"Patient appears to be exaggerating the pain.",bin:"subjective",feedback:"This assigns a motive you cannot know, and it prejudices every clinician who reads the chart afterwards."},{id:"t3-s7",text:"Patient rated pain 8 out of 10 in the right lower abdomen.",bin:"objective",feedback:"Pain is self-reported, and recording the patient's own number is the objective way to capture it."},{id:"t3-s8",text:"Patient is non-compliant with the medication schedule.",bin:"subjective",feedback:"'Non-compliant' is a label. The fact is what they told you: how many doses, and what they said about why."},{id:"t3-s9",text:"Patient reports taking two of the four prescribed doses this week.",bin:"objective",feedback:"Specific, quoted from the patient, and free of any conclusion about why."},{id:"t3-s10",text:"Wound 3 cm, edges approximated, no drainage noted.",bin:"objective",feedback:"Measured and described. Another person examining it would write the same thing."}]},{kind:"rewrite",title:"Replace judgmental language",instructions:"Each entry below would be a problem in a real record. Write the objective version, then compare with a model.",items:[{id:"t3-r1",before:"Patient was rude and uncooperative during the visit.",problem:"Two judgments and no facts. A reader learns your opinion of the patient and nothing about what happened.",model:"Patient raised their voice when asked to repeat their date of birth and declined to complete the intake form.",rubric:["Describes observable behavior rather than labeling the person","Contains no words that judge character (rude, difficult, uncooperative)","A different staff member observing the same visit could have written it","Grammar and spelling are correct"]},{id:"t3-r2",before:"Patient obviously did not understand the instructions.",problem:"'Obviously' asserts something about the patient's mind. You can report what they said or did, not what they understood.",model:"When asked to repeat the medication schedule, patient stated, “I take them all at night, right?” The schedule is one tablet each morning.",rubric:["Reports what the patient said or did, not what they knew","Uses a direct quotation where the patient's own words matter","Includes the fact that makes the entry meaningful","Contains no words asserting a mental state"]},{id:"t3-r3",before:"Patient seemed fine and was probably just tired.",problem:"'Seemed', 'probably', and 'just' are all hedges around a guess. In a record that later matters, this entry says nothing.",model:"Patient was alert and oriented, answered all intake questions, and reported sleeping approximately four hours last night.",rubric:["Every statement is something observed or reported","No hedging words (seemed, probably, apparently, just)","Includes specifics rather than general impressions","Could be defended if the chart were reviewed"]}]},{kind:"grammar-drill",title:"Grammar and spelling corrections",instructions:"Nouns, verbs, and pronouns, in the sentences you will actually write.",items:[{id:"t3-g1",prompt:"Which sentence puts the action in the active voice, with the doer as the subject?",principle:"Active voice names who did what. In documentation this matters: 'the medication was refused' leaves out who refused it.",choices:[{text:"The medication was refused.",correct:!1,rationale:"Passive. The reader does not learn who refused — the patient, a family member, or someone else."},{text:"The patient refused the medication.",correct:!0,rationale:"Correct. Subject (patient), action verb (refused), object (medication). Nothing is left to inference."},{text:"Refusal of the medication occurred at 1400.",correct:!1,rationale:"The time is useful but the doer has vanished into a noun. Who refused?"},{text:"It was decided that the medication would not be given.",correct:!1,rationale:"Doubly vague — no doer, and 'decided' hides whether the patient declined or a clinician withheld it."}]},{id:"t3-g2",prompt:"Which sentence uses a pronoun that a reader could not misread?",principle:"A pronoun must have exactly one possible antecedent. When two people appear, repeat the noun.",choices:[{text:"The assistant told the patient that she needed to fast.",correct:!1,rationale:"'She' could be the assistant or the patient. In a record, that ambiguity can invert the meaning."},{text:"The assistant told the patient that the patient needed to fast.",correct:!0,rationale:"Correct. Repeating the noun is slightly clunky and completely unambiguous. Clarity wins."},{text:"She told her that she needed to fast.",correct:!1,rationale:"Three pronouns and no clear referent for any of them."},{text:"The patient was told by her that she needed to fast.",correct:!1,rationale:"Passive and still ambiguous — both 'her' and 'she' are unresolved."}]},{id:"t3-g3",prompt:"Which entry documents an observation rather than an assumption?",principle:"You may document what you saw, measured, or were told. You may not document what you concluded about a person.",choices:[{text:"Patient was clearly in a lot of pain.",correct:!1,rationale:"'Clearly' and 'a lot' are your assessment. Record the behavior or the patient's own rating."},{text:"Patient guarded the right side when standing and rated pain 7 out of 10.",correct:!0,rationale:"Correct. One observed behavior and one self-reported number — both verifiable."},{text:"Patient did not seem to be in much distress.",correct:!1,rationale:"'Did not seem' is an impression, and a wrong one in the record can affect later care decisions."},{text:"Patient is a complainer.",correct:!1,rationale:"A label attached to the person. This has no clinical value and would be indefensible if the record were reviewed."}]},{id:"t3-g4",prompt:"Which sentence is spelled correctly?",principle:"Topic 3 words: evidence, Wednesday, dilated, nauseous, consciousness. Wednesday keeps a silent 'd' most people drop.",choices:[{text:"Patient reported feeling nauseus on Wendsday.",correct:!1,rationale:"Two errors: 'nauseous' and 'Wednesday'."},{text:"Patient reported feeling nauseous on Wednesday.",correct:!0,rationale:"Correct on both. Note the silent 'd' in Wednesday."},{text:"Patient reported feeling nauseous on Wendesday.",correct:!1,rationale:"'Nauseous' is right; 'Wednesday' is not."},{text:"Patient reported feeling nausious on Wednesday.",correct:!1,rationale:"'Wednesday' is right; the word is 'nauseous'."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:3}],product:{label:"Brief patient encounter note",description:"Write a short objective encounter note from the scenario below. Include what you observed, what the patient reported (quoted where their words matter), and what was done. Include no interpretations, no labels, and no conclusions about the patient. Four to six sentences.",scenario:"A patient arrives 20 minutes late for a scheduled blood pressure check. They tell you they ran for the bus. You measure blood pressure at 152/94 in the right arm, seated. They mention they stopped taking one of their medications about two weeks ago because it “made them feel strange,” and they have not called the office about it. You take a second reading after five minutes of rest: 138/86."},reflection:["Read your note and circle every word that describes what you thought rather than what you saw. Remove them.","Would another assistant who saw the same visit write something close to what you wrote?","If this note were read aloud two years from now, is there anything in it you would want to take back?"],beforeYouLeave:["Completed the fact-or-opinion sort","Rewrote all three judgmental entries and scored them against the rubric","Reviewed Word Bank List 3","Drafted the encounter note and checked it against the Communication Check"]},{number:4,slug:"4",title:"SOAP Notes: Organizing Clinical Information",unit:{number:2,title:"Clinical Documentation"},sessions:"1",goals:["documentation","grammar-sentence","summarizing"],spiralsFrom:[2,3],essentialQuestion:"How does organized documentation help another healthcare professional understand the patient?",concepts:["The purpose of clinical documentation: someone who was not there must be able to reconstruct what happened","SOAP structure — Subjective, Objective, Assessment, Plan","Subjective is what the patient tells you; Objective is what you measure or observe","Assessment and Plan are the provider's clinical judgment — know where your contribution ends","Relevant versus irrelevant information: a note that includes everything hides what matters","Documentation sequence: information in a predictable order can be read quickly under pressure"],grammar:[{heading:"Agreements",points:["Subject–verb agreement, including when a phrase separates the subject from its verb","Pronoun–noun agreement","Clear pronoun reference — every pronoun points to exactly one noun"]}],wordListNumber:4,practice:[{kind:"sorter",title:"Sort into S, O, A, and P",instructions:"Which section does each piece of information belong in? Ask who the information came from and whether it is measured or judged.",bins:[{id:"s",label:"Subjective",hint:"What the patient reports"},{id:"o",label:"Objective",hint:"What you measure or observe"},{id:"a",label:"Assessment",hint:"The provider's clinical judgment"},{id:"p",label:"Plan",hint:"What will happen next"}],items:[{id:"t4-s1",text:"“My throat has been sore for three days.”",bin:"s",feedback:"The patient's own report, in their own words. Subjective."},{id:"t4-s2",text:"Temperature 100.8\xb0F, oral.",bin:"o",feedback:"A measurement you took. Objective."},{id:"t4-s3",text:"Rapid strep test performed; result negative.",bin:"o",feedback:"A test you performed and its result. Objective — the finding, not what it means."},{id:"t4-s4",text:"Likely viral pharyngitis.",bin:"a",feedback:"A clinical conclusion drawn from the findings. Assessment — and the provider's to make, not yours."},{id:"t4-s5",text:"Return in 5 days if symptoms have not improved.",bin:"p",feedback:"What happens next. Plan."},{id:"t4-s6",text:"“I've been taking ibuprofen but it isn't helping much.”",bin:"s",feedback:"Reported by the patient. Subjective, even though it concerns a medication."},{id:"t4-s7",text:"Throat erythematous, no exudate noted.",bin:"o",feedback:"An observation from examination. Objective."},{id:"t4-s8",text:"Supportive care discussed; fluids and rest advised.",bin:"p",feedback:"The course of action decided. Plan."}]},{kind:"sequencer",title:"Put the note in order",instructions:"Arrange these into the sequence a colleague could read quickly under pressure.",items:[{id:"t4-q1",text:"Subjective — the patient's reported symptoms and history",position:1,reason:"The note opens with why the patient came, in their own account. It frames everything that follows."},{id:"t4-q2",text:"Objective — vital signs, examination findings, test results",position:2,reason:"What was measured comes after what was reported, so the reader can compare the two."},{id:"t4-q3",text:"Assessment — the provider's clinical impression",position:3,reason:"Judgment follows evidence. An assessment stated before its findings cannot be evaluated."},{id:"t4-q4",text:"Plan — treatment, instructions, and follow-up",position:4,reason:"The note ends with what happens next, which is what the next reader most often needs."}]},{kind:"grammar-drill",title:"Agreement and documentation editing",instructions:"Spot the agreement error, and the entry that oversteps.",items:[{id:"t4-g1",prompt:"Which sentence has correct subject–verb agreement?",principle:"A phrase between the subject and the verb does not change the subject. 'Each' and 'every' are singular.",choices:[{text:"Each of the test results were reviewed with the patient.",correct:!1,rationale:"'Each' is singular, so it takes 'was'. 'Results' is not the subject."},{text:"Each of the test results was reviewed with the patient.",correct:!0,rationale:"Correct. 'Each' is singular and takes the singular verb 'was'."},{text:"Each of the test result were reviewed with the patient.",correct:!1,rationale:"Two errors: 'result' should be plural in the phrase, and the verb should be 'was'."},{text:"Each of the test results are reviewed with the patient.",correct:!1,rationale:"'Are' is plural. 'Each' requires 'is' or 'was'."}]},{id:"t4-g2",prompt:"A medical assistant is writing a SOAP note. Which entry is outside their scope?",principle:"Medical assistants document what the patient reported and what was measured. Assessment is clinical judgment and belongs to the provider.",choices:[{text:"S: “My throat has been sore for three days.”",correct:!1,rationale:"A quoted patient report. Squarely within scope."},{text:"O: Temperature 100.8\xb0F, oral. Throat erythematous.",correct:!1,rationale:"Measurements and observations. Within scope."},{text:"A: Likely viral pharyngitis; antibiotics not indicated.",correct:!0,rationale:"Correct — this is the problem entry. It is a diagnosis and a treatment judgment, both of which belong to the provider."},{text:"P: Patient given written instructions for fluids and rest.",correct:!1,rationale:"Recording that instructions were given is documentation of what was done. Within scope."}]},{id:"t4-g3",prompt:"Which piece of information does NOT belong in this visit's note for a sore throat?",principle:"Relevance is a safety feature. A note padded with unrelated detail buries the information the next reader needs.",choices:[{text:"Onset and duration of the sore throat",correct:!1,rationale:"Directly relevant to why the patient came."},{text:"Current temperature",correct:!1,rationale:"Relevant — it bears on the presenting complaint."},{text:"The patient mentioned they are planning a holiday next month",correct:!0,rationale:"Correct. Pleasant conversation, no clinical bearing. Including it lengthens the note and hides what matters."},{text:"Medications the patient has already tried",correct:!1,rationale:"Relevant — it affects what to try next."}]}]},{kind:"builder",storageKey:"soap",title:"Build a SOAP note",instructions:"Write each section from the case below. Keep Subjective in the patient's words and Objective to what was measured. For Assessment, write what a provider would need from you — not a diagnosis of your own.",scenario:"A patient comes in reporting a sore throat that began three days ago. They say it hurts most when swallowing and that ibuprofen has helped only a little. They deny cough. You measure temperature 100.8\xb0F oral, pulse 88, respirations 16. On inspection the throat appears red with no visible white patches. A rapid strep test is performed and is negative. The provider advises fluids, rest, and a return visit in five days if there is no improvement.",fields:[{id:"s",label:"S — Subjective",prompt:"What the patient reported. Quote them where their exact words matter.",expects:["sore throat","three days","3 days"],missingHint:"A reader needs the complaint and how long it has been going on."},{id:"o",label:"O — Objective",prompt:"What you measured and observed. Numbers with their units.",expects:["100.8","temp"],missingHint:"Include the vital signs you measured, with values."},{id:"a",label:"A — Assessment",prompt:"Summarize the findings for the provider. Do not write a diagnosis — that is the provider's.",rows:2},{id:"p",label:"P — Plan",prompt:"What was advised and what happens next, including follow-up.",expects:["five days","5 days","return","follow"],missingHint:"The plan should state the follow-up interval so the next reader knows when to expect them back."}]},{kind:"word-bank",title:"Words to spell",listNumber:4}],product:{label:"Basic SOAP note",description:"Complete the guided SOAP note from the case above. Each section holds only what belongs in it, agreements are correct, and every pronoun has one clear referent. Submit through Brightspace."},reflection:["Could a colleague who has never met this patient act on your note?","Is anything in your Objective section actually an interpretation?","Did you include anything a reader does not need?"],beforeYouLeave:["Sorted all eight items into S, O, A, and P","Put the note sections into the correct sequence","Completed the agreement drill","Built the SOAP note and ran the completeness check"]},{number:5,slug:"5",title:"Handoffs, Messages & Professional Communication",unit:{number:2,title:"Clinical Documentation"},sessions:"1",goals:["documentation","professional-writing","summarizing","grammar-sentence"],spiralsFrom:[3,4],essentialQuestion:"What information does another healthcare professional need from me to safely continue the patient's care?",concepts:["Relevant information: what the next person must know to act safely","Prioritization — the most important thing goes first, not last","Conciseness without omission","SBAR as a communication framework: Situation, Background, Assessment, Recommendation","Closed-loop communication — the receiver repeats it back so both people know it landed","Avoiding ambiguity: 'soon', 'a lot', and 'later' mean different things to different people"],grammar:[{heading:"Adjectives and adverbs",points:["What each one modifies: adjectives describe nouns, adverbs describe verbs, adjectives, and other adverbs","Changing adjectives into adverbs — usually by adding -ly","good / better / best, and the difference between 'good' and 'well'","less versus fewer: less for amounts you cannot count, fewer for things you can","much versus many, on the same principle"]},{heading:"Verb tenses",points:["Present, past, and future, and what each one signals in a handoff","Progressive forms (helping verb + -ing) for action that is ongoing right now","Avoiding shifting tenses mid-report, which makes the timeline unreadable"]}],wordListNumber:5,practice:[{kind:"grammar-drill",title:"Adjectives, adverbs, and tense",instructions:"The grammar of a handoff — precision about quantity, degree, and when.",items:[{id:"t5-g1",prompt:"Which sentence uses 'fewer' and 'less' correctly?",principle:"Fewer for things you can count individually. Less for quantities you measure rather than count.",choices:[{text:"The patient had less episodes of dizziness and fewer fluid intake today.",correct:!1,rationale:"Both are reversed. Episodes can be counted (fewer); fluid intake is measured (less)."},{text:"The patient had fewer episodes of dizziness and less fluid intake today.",correct:!0,rationale:"Correct. Countable episodes take 'fewer'; measurable intake takes 'less'."},{text:"The patient had less episodes of dizziness and less fluid intake today.",correct:!1,rationale:"'Episodes' are countable, so they need 'fewer'."},{text:"The patient had fewer episodes of dizziness and fewer fluid intake today.",correct:!1,rationale:"'Fluid intake' is measured, not counted, so it needs 'less'."}]},{id:"t5-g2",prompt:"Which sentence keeps the tense consistent?",principle:"Shifting tense mid-report makes the timeline ambiguous, and in a handoff the timeline is the point.",choices:[{text:"The patient arrived at 0900, reports chest tightness, and was given aspirin.",correct:!1,rationale:"Past, present, past. The reader cannot tell whether the chest tightness is current."},{text:"The patient arrived at 0900, reported chest tightness, and was given aspirin.",correct:!0,rationale:"Correct. All past tense — a consistent account of what has already happened."},{text:"The patient arrives at 0900, reported chest tightness, and is given aspirin.",correct:!1,rationale:"Present, past, present. The sequence is impossible to follow."},{text:"The patient was arriving at 0900 and reports chest tightness.",correct:!1,rationale:"The progressive form suggests an ongoing arrival, and the tense still shifts."}]},{id:"t5-g3",prompt:"Which phrase should be removed from a handoff because it is ambiguous?",principle:"Vague quantifiers are where handoffs fail. If two people could read it differently, replace it with a number or a time.",choices:[{text:"Pain rated 7 out of 10",correct:!1,rationale:"A specific self-reported number. Unambiguous."},{text:"Last dose given at 1400",correct:!1,rationale:"A specific time. Unambiguous."},{text:"Should be seen fairly soon",correct:!0,rationale:"Correct. 'Fairly soon' could mean ten minutes or two hours. Say when, or say what would trigger escalation."},{text:"Allergic to penicillin — hives and throat swelling",correct:!1,rationale:"Names the allergen and the reaction. Exactly what the next person needs."}]},{id:"t5-g4",prompt:"A colleague repeats your handoff back to you with one detail wrong. What should you do?",principle:"Closed-loop communication exists so errors surface at the handoff instead of at the bedside. The read-back working is the system succeeding.",choices:[{text:"Let it go — they have the important parts",correct:!1,rationale:"The detail you would let go is the one that reaches the patient wrong."},{text:"Correct the detail and ask them to repeat that part back again",correct:!0,rationale:"Correct. That is the loop closing. It costs ten seconds and is the entire point of a read-back."},{text:"Write it in the chart instead so it is documented",correct:!1,rationale:"Documenting is necessary but does not fix a colleague who is about to act on wrong information now."},{text:"Assume they misspoke and will remember correctly",correct:!1,rationale:"A read-back reflects what they actually heard. If it came back wrong, that is what they hold."}]}]},{kind:"rewrite",title:"Fix an unclear handoff",instructions:"Each of these was said at a shift change. Rewrite so the next person can act on it.",items:[{id:"t5-r1",before:"Room 4 isn't doing great, you might want to keep an eye on them.",problem:"No name, no measurement, no threshold. 'Keep an eye' does not say what to watch or what to do.",model:"Room 4, Ms. Alvarez: respirations rose from 16 this morning to 24 at 1430, oxygen saturation 92%. Recheck within the hour, and notify the provider if saturation drops below 90%.",rubric:["Identifies the patient by name, not by room alone","Includes measured values and how they changed","States what to do and when","States a threshold for escalation"]},{id:"t5-r2",before:"The patient in bed 2 has some allergies so be careful with meds.",problem:"'Some allergies' and 'be careful' give the receiver nothing usable. Which allergen, and what reaction?",model:"Bed 2, Mr. Osei: allergic to penicillin — reaction is hives and throat swelling. Documented in the chart and on his band.",rubric:["Names the specific allergen","States the specific reaction, not just that one exists","Confirms where it is documented","Contains no vague instruction like 'be careful'"]}]},{kind:"builder",storageKey:"sbar",title:"Build an SBAR handoff",instructions:"Four sections. Situation is why you are calling right now; Background is what led here; Assessment is what you are seeing; Recommendation is what you are asking for.",scenario:"You are a patient care technician on a medical unit. Ms. Lena Okafor in room 312 was admitted two days ago for management of a leg infection. This morning her pulse was 74 and she was talkative. At 1500 you record pulse 112, respirations 24, temperature 101.6\xb0F, and she is quieter than usual and says she feels “strange.” Her blood pressure is 98/60, down from 128/78 this morning. You are calling the nurse.",fields:[{id:"s",label:"S — Situation",prompt:"Who you are, who the patient is, and why you are calling — in one or two sentences.",expects:["okafor","312"],missingHint:"Identify the patient by name or room so the nurse knows immediately who this concerns.",rows:2},{id:"b",label:"B — Background",prompt:"The relevant history. Why is this patient here, and what has been happening?",expects:["infection","admitted"],missingHint:"Include why the patient is admitted — it frames everything else."},{id:"a",label:"A — Assessment",prompt:"What you are observing now, with numbers and how they have changed. Report; do not diagnose.",expects:["112","101.6","24","98"],missingHint:"Include the measured values. A change described without numbers cannot be judged."},{id:"r",label:"R — Recommendation",prompt:"What you are asking for. Be direct — 'I need you to come and see her now' is appropriate.",expects:["see","come","assess","review","now"],missingHint:"State what you want to happen. A report with no request leaves the nurse to guess the urgency.",rows:2}]},{kind:"word-bank",title:"Words to spell",listNumber:5}],product:{label:"Written handoff / SBAR message",description:"Produce a written SBAR communication from the scenario above. It must be complete enough that the receiver needs to ask you nothing, and short enough to be read in under thirty seconds."},reflection:["If the person receiving this could not reach you afterwards, would they still have everything they need?","Did you state what you want to happen, or only what you observed?","Are there any vague quantifiers left — soon, a lot, a bit, slightly?"],beforeYouLeave:["Completed the adjective, adverb, and tense drill","Rewrote both unclear handoffs","Built the SBAR and ran the completeness check","Reviewed Word Bank List 5, including the spiral words"]},{number:6,slug:"6",title:"Writing Clear Patient Instructions",unit:{number:3,title:"Patient Communication"},sessions:"2",goals:["patient-centered","grammar-sentence","professional-writing"],spiralsFrom:[2,3],essentialQuestion:"How do I communicate healthcare information so a patient can actually understand and use it?",concepts:["Health literacy — a large share of adults find standard medical instructions hard to act on, and that says nothing about their intelligence","Medical jargon versus patient-friendly language","Sequencing: instructions in the order the patient will do them","Audience awareness — you are not writing for a colleague","Tell the patient what to do, rather than only giving them information"],grammar:[{heading:"Strong sentences",points:["Simple versus complex sentences, and why simple usually wins in instructions","Sentence fragments — and the one place they are acceptable","Run-ons and comma splices","Transition words that show sequence: first, next, then, after, finally"]},{heading:"Imperative sentences",points:["The imperative gives a direct instruction: 'Take one tablet each morning'","The subject 'you' is understood rather than written","Imperatives are shorter and clearer than 'the patient should' constructions"]}],wordListNumber:6,practice:[{kind:"matcher",title:"Translate the jargon",instructions:"Match each clinical term to plain language, then practise saying it to a patient.",pairs:[{id:"t6-m1",term:"hypertension",plain:"high blood pressure",explanation:"Your blood pressure is higher than it should be. That means your heart is working harder than it needs to."},{id:"t6-m2",term:"NPO after midnight",plain:"nothing to eat or drink after midnight",explanation:"Do not eat or drink anything — including water — after midnight tonight. If you take morning medications, ask us which ones to take with a small sip."},{id:"t6-m3",term:"administer topically",plain:"put it on the skin",explanation:"Put a thin layer on the skin over the sore area. It is not something you swallow."},{id:"t6-m4",term:"adverse reaction",plain:"a harmful side effect",explanation:"If the medicine makes you feel worse rather than better, stop taking it and call us right away."},{id:"t6-m5",term:"ambulate",plain:"walk",explanation:"Try to get up and walk a short distance a few times a day, as long as it does not hurt."},{id:"t6-m6",term:"contraindicated",plain:"not safe to use in your case",explanation:"This medicine is not safe to take with the other one you are on, so we are using a different one."}]},{kind:"sequencer",title:"Put the instructions in a safe order",instructions:"These wound-care steps are scrambled. Order them the way the patient will actually do them.",items:[{id:"t6-q1",text:"Wash your hands with soap and water.",position:1,reason:"Hand washing comes first. Touching a wound with unwashed hands is how an infection starts, so this cannot come later."},{id:"t6-q2",text:"Take off the old bandage and throw it away.",position:2,reason:"The old dressing comes off before you can see or clean the wound."},{id:"t6-q3",text:"Rinse the wound gently with clean water.",position:3,reason:"Clean the wound once it is uncovered and before anything new goes on it."},{id:"t6-q4",text:"Pat the skin around the wound dry with a clean towel.",position:4,reason:"A dressing will not stick to wet skin, so drying comes after rinsing and before the new bandage."},{id:"t6-q5",text:"Put on a new bandage.",position:5,reason:"The new dressing goes on last, over a clean and dry area."},{id:"t6-q6",text:"Wash your hands again.",position:6,reason:"Hand washing bookends the task. Your hands touched a used dressing, so they are washed again at the end."}]},{kind:"rewrite",title:"Fix confusing instructions",instructions:"Each of these was given to a real-seeming patient and did not work. Rewrite it.",items:[{id:"t6-r1",before:"Patient should administer the prescribed analgesic PRN for post-operative discomfort and monitor the incision site for signs of infection.",problem:"Written for a colleague. 'Analgesic', 'PRN', 'post-operative', and 'signs of infection' all assume training the patient does not have.",model:"Take one pain tablet when you need it, up to four times a day. Look at the cut once a day. Call us if it becomes more red, more painful, or starts leaking fluid, or if you get a fever.",rubric:["Uses the imperative — tells the patient what to do","Replaces every piece of jargon with a plain word","Says what 'signs of infection' actually look like","Gives a specific limit or frequency, not 'as needed'"]},{id:"t6-r2",before:"Take your medication regularly and be sure to stay well hydrated throughout the day.",problem:"'Regularly' and 'well hydrated' mean nothing specific. The patient cannot follow this even if they want to.",model:"Take one tablet every morning with breakfast. Drink about six to eight glasses of water a day.",rubric:["States how much and how often, with numbers","Ties the dose to something in the patient's day","Replaces vague quantifiers with specific amounts","Would produce the same behavior from any two readers"]},{id:"t6-r3",before:"If symptoms worsen or fail to improve within an appropriate timeframe, contact the office.",problem:"The patient does not know what 'worsen' means here or what an appropriate timeframe is. Under pressure they will guess, and they may guess late.",model:"Call us if the pain gets worse, if you get a fever over 100.4\xb0F, or if you are not feeling better in three days. If you have trouble breathing, call 911.",rubric:["Names the specific symptoms that should prompt a call","Gives a number for the timeframe","Separates 'call us' from 'this is an emergency'","Could be acted on by someone frightened and distracted"]}]},{kind:"grammar-drill",title:"Fragments, run-ons, and the imperative",instructions:"The sentence grammar that makes instructions work.",items:[{id:"t6-g1",prompt:"Which is the clearest instruction for a patient?",principle:"The imperative gives a direct instruction with the subject 'you' understood. It is shorter and leaves less room for doubt.",choices:[{text:"The patient should ensure that the medication is taken each morning.",correct:!1,rationale:"Third person and passive. The patient reading it may not register that 'the patient' means them."},{text:"Take one tablet each morning with breakfast.",correct:!0,rationale:"Correct. Imperative, specific, and tied to a moment in the patient's day."},{text:"Medication administration should occur in the morning hours.",correct:!1,rationale:"No doer, no dose, and 'morning hours' is vaguer than 'with breakfast'."},{text:"It is recommended that morning dosing be observed.",correct:!1,rationale:"Doubly passive and reads as optional. A recommendation the patient may not follow."}]},{id:"t6-g2",prompt:"Which sentence is a run-on that needs fixing?",principle:"Two complete sentences joined by only a comma is a comma splice. In instructions this matters, because the reader loses where one step ends.",choices:[{text:"Wash your hands, then remove the old bandage.",correct:!1,rationale:"Correct as written. 'Then' plus a comma links the steps properly."},{text:"Wash your hands, remove the old bandage, rinse the wound with clean water, pat it dry, put on a new bandage.",correct:!0,rationale:"Correct — this is the run-on. Five instructions strung together with commas. Break them into separate sentences or a numbered list."},{text:"Wash your hands. Remove the old bandage.",correct:!1,rationale:"Two clear sentences, correctly separated."},{text:"After washing your hands, remove the old bandage.",correct:!1,rationale:"Correct. A dependent clause followed by a main clause, properly punctuated."}]},{id:"t6-g3",prompt:"Which transition word best signals that this is the last step?",principle:"Sequence transitions tell the reader where they are in a process. Using them consistently prevents a patient stopping halfway.",choices:[{text:"Also",correct:!1,rationale:"'Also' adds an item without signalling position. The reader does not know they are finishing."},{text:"Finally",correct:!0,rationale:"Correct. 'Finally' tells the reader this is the last step, which is genuinely reassuring in a set of instructions."},{text:"However",correct:!1,rationale:"'However' signals contrast, which would confuse a sequence."},{text:"Meanwhile",correct:!1,rationale:"'Meanwhile' suggests two things happening at once — the opposite of a final step."}]},{id:"t6-g4",prompt:"Which sentence uses 'once' and 'ones' correctly?",principle:"Topic 6 confusables. 'Once' means one time; 'ones' is the plural of 'one' standing in for a noun.",choices:[{text:"Change the bandage ones a day and use the clean once from the box.",correct:!1,rationale:"Both are reversed."},{text:"Change the bandage once a day and use the clean ones from the box.",correct:!0,rationale:"Correct. 'Once a day' means one time daily; 'the clean ones' stands in for 'the clean bandages'."},{text:"Change the bandage once a day and use the clean once from the box.",correct:!1,rationale:"'Once a day' is right, but the second should be 'ones'."},{text:"Change the bandage ones a day and use the clean ones from the box.",correct:!1,rationale:"The second is right; the first should be 'once'."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:6}],product:{label:"Patient instruction sheet",description:"Write a one-page instruction sheet a patient could follow at home without calling for clarification. Use imperatives, number the steps, replace every piece of jargon, and say specifically when to call the office and when to call 911.",scenario:"Choose one: caring for a wound after minor stitches; preparing for a procedure that requires nothing to eat or drink after midnight; taking a new blood pressure medication; or monitoring blood pressure at home with a cuff."},reflection:["Give your sheet to someone outside healthcare. Ask them to tell you what they would do first — not whether it makes sense.","Did you say what to do, or only what the situation is?","Is there any word on the page you would not use with a neighbour?"],beforeYouLeave:["Matched all six jargon terms and drafted plain-language explanations","Put the wound-care steps into a safe order","Rewrote all three confusing instructions","Drafted the instruction sheet and checked it against the Communication Check"]},{number:7,slug:"7",title:"Patient Messages, Reminders & Follow-Up",unit:{number:3,title:"Patient Communication"},sessions:"1–2",goals:["patient-centered","professional-writing","grammar-sentence"],spiralsFrom:[2,3,6],essentialQuestion:"How can I communicate important information briefly without sounding abrupt or unclear?",concepts:["Concise writing — short is not the same as curt","Essential versus unnecessary information: what does the reader need to act?","Professional tone in a very short message, where there is no room to recover from a bad line","Patient-centered language","A call to action — every message should make clear what happens next and who does it","Confirming understanding without sounding like a test"],grammar:{note:"The Instructor's Guide directs this topic to revisit earlier grammar rather than introduce new items, and does not specify which. The practice below spirals subject–verb agreement, fragments and run-ons, and pronoun clarity from Topics 2, 3, and 6. Confirm which items should be prioritized here."},wordListNumber:7,practice:[{kind:"choose-best",title:"Too much, too little, or just right?",scenario:"A patient is due for a follow-up appointment on Tuesday 14 October at 10:00 a.m. with Dr. Reyes. They need to arrive 15 minutes early and bring their current medication list. You are writing the reminder message they will see in the patient portal.",instructions:"One of these is right. The others fail in a specific way — read every explanation.",items:[{id:"t7-c1",prompt:"Which reminder should you send?",principle:"A good reminder carries exactly what the patient must know to show up correctly: when, where, and what to bring. Anything else competes with those three.",choices:[{text:"Appointment Tuesday 10am.",correct:!1,rationale:"Too little. No date, no provider, no arrival time, nothing about the medication list. The patient may arrive on the wrong Tuesday."},{text:"Hello, we hope this message finds you well. We are writing to remind you that as part of our ongoing commitment to your continued health and wellbeing, we have you scheduled for a follow-up consultation appointment with one of our providers here at the practice. Please make every effort to arrive in a timely manner and bring along any relevant materials.",correct:!1,rationale:"Too much, and it still omits the date, the time, the provider, and what to bring. Length is not the same as completeness."},{text:"Reminder: follow-up with Dr. Reyes on Tuesday, 14 October at 10:00 a.m. Please arrive by 9:45 and bring your current medication list. Call 555-0134 if you need to reschedule.",correct:!0,rationale:"Correct. Date, time, provider, arrival time, what to bring, and what to do if it does not work — in four lines."},{text:"You have an appointment coming up soon. Don't forget to bring everything you need and don't be late.",correct:!1,rationale:"Vague on every point and faintly scolding. 'Don't be late' reads as an accusation rather than an arrival time."}]},{id:"t7-c2",prompt:"The patient replies asking whether they still need to fast. Fasting is not required. Which reply is best?",principle:"Answer the question first, then add anything else. A reply that buries the answer makes the patient read twice to find it.",choices:[{text:"No.",correct:!1,rationale:"Accurate and abrupt. A one-word reply to a worried question reads as dismissive, even when it is correct."},{text:"No fasting is needed for this visit — you can eat and drink normally. Please still bring your medication list. See you Tuesday at 10:00.",correct:!0,rationale:"Correct. Answers the question in the first four words, confirms what that means in practice, and repeats the key details."},{text:"Thanks for reaching out! Great question. Let me look into that for you and get back to you as soon as I can.",correct:!1,rationale:"Warm but useless — you already know the answer. Delaying a known answer wastes the patient's time and yours."},{text:"Fasting requirements vary by procedure type and are determined by the ordering provider based on the clinical indication.",correct:!1,rationale:"True in general and no help at all. The patient asked about their appointment, not about policy."}]}]},{kind:"tone",title:"Tone continuum",instructions:"Place each message, then rewrite the ones that miss. Watch the over-soft end as carefully as the blunt end.",samples:[{id:"t7-t1",text:"You missed your appointment yesterday. You need to call and reschedule.",band:0,feedback:"Blunt. It opens with the patient's failure and issues an order. Nothing here is untrue, and most people receiving it would feel told off.",professional:"We missed you at yesterday's appointment. When you have a moment, call us at 555-0134 and we will find a new time that works."},{id:"t7-t2",text:"Your results are in. Call the office.",band:1,feedback:"Abrupt, and in this context genuinely worrying — a patient reading it will assume the news is bad. Two more words would fix it.",professional:"Your test results are back and Dr. Reyes would like to go over them with you. Please call us at 555-0134 when you can. There is nothing urgent to worry about."},{id:"t7-t3",text:"Hi Ms. Alvarez — your prescription is ready for pickup at the front desk any time before 5:00 p.m. this week. Let us know if you need it sent to your pharmacy instead.",band:2,feedback:"Professional. Warm opening, specific information, a clear deadline, and an alternative offered. Nothing wasted."},{id:"t7-t4",text:"Hi there! I hope you don't mind me reaching out, and I'm so sorry to bother you — I was just wondering if you might possibly have a moment at some point to maybe think about scheduling that follow-up we mentioned, if that's at all convenient for you?",band:3,feedback:"Over-soft. So hedged that the patient may not realize anything is being asked. Apologizing for doing your job also undercuts you.",professional:"Hi Ms. Alvarez — it is time to book your follow-up. Call us at 555-0134 or reply here and we will get it scheduled."}]},{kind:"grammar-drill",title:"Spiral review",instructions:"Grammar from Topics 2, 3, and 6, in the short messages you are writing now.",items:[{id:"t7-g1",prompt:"Which message has correct subject–verb agreement?",principle:"Spiral from Topic 2. A phrase between subject and verb does not change which verb you need.",choices:[{text:"The list of your current medications are needed at check-in.",correct:!1,rationale:"The subject is 'list', which is singular, so it takes 'is'. 'Medications' sits inside a phrase."},{text:"The list of your current medications is needed at check-in.",correct:!0,rationale:"Correct. Singular subject 'list' takes 'is'."},{text:"The lists of your current medication is needed at check-in.",correct:!1,rationale:"Here the plural 'lists' would need 'are'."},{text:"Your current medications list are needed at check-in.",correct:!1,rationale:"'List' is still the subject and still singular."}]},{id:"t7-g2",prompt:"Which message avoids an unclear pronoun?",principle:"Spiral from Topic 3. In a short message there is no context to recover a pronoun's meaning from.",choices:[{text:"We sent your results to Dr. Reyes and she will call you about it.",correct:!1,rationale:"'It' has no clear referent — the results, the call, or something else. In a two-line message this is genuinely confusing."},{text:"We sent your results to Dr. Reyes, and she will call you to discuss them.",correct:!0,rationale:"Correct. 'Them' clearly refers to the results, and 'she' to Dr. Reyes."},{text:"They sent them to her and she will call you about them.",correct:!1,rationale:"Four pronouns, none anchored."},{text:"It was sent and they will be in touch about it.",correct:!1,rationale:"No named actor at all. The patient learns nothing."}]},{id:"t7-g3",prompt:"Which of these is a fragment that should not be sent as written?",principle:"Spiral from Topic 6. Fragments work in a bulleted list. In running message text they leave the reader waiting.",choices:[{text:"Because your insurance information has changed.",correct:!0,rationale:"Correct — this is the fragment. It begins with 'because' and never says what follows from it. The patient is left waiting for the point."},{text:"Please bring your new insurance card to your next visit.",correct:!1,rationale:"A complete imperative sentence."},{text:"Your insurance information has changed, so please bring your new card.",correct:!1,rationale:"Two clauses correctly joined by a comma and 'so'."},{text:"Bring your new card.",correct:!1,rationale:"Short but complete — an imperative with the subject 'you' understood."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:7}],product:{label:"Patient portal message",description:"Write a patient portal message about an appointment, a follow-up, a preparation requirement, or missing information. Two to four sentences. It must answer the patient's likely question first, state clearly what happens next, and sound like a person wrote it.",scenario:"A patient's insurance changed since their last visit and the front desk could not verify coverage for Thursday's appointment. The visit can still go ahead, but they need to bring the new card, and if coverage cannot be verified they may be billed as self-pay. Write the message they will see."},reflection:["Read your message as though you were worried about your health. Does the first line reassure or alarm?","Is the action you want the patient to take stated, or implied?","Could you cut a sentence without losing anything the patient needs?"],beforeYouLeave:["Completed the too-much / too-little / just-right exercise","Placed all four messages on the tone continuum and rewrote the three that missed","Completed the spiral grammar review","Drafted the portal message and checked it against the Communication Check"]},{number:8,slug:"8",title:"Referrals, Prior Authorizations & Requests",unit:{number:3,title:"Patient Communication"},sessions:"1–2",sessionsNote:{note:"Source conflict: the Instructor's Guide summary table lists Topic 8 as 1 session; the detailed outline heading for Topic 8 says 2 sessions. Confirm which is correct — this also bears on the overall session count against the Fall 1 calendar."},goals:["professional-writing","documentation","summarizing"],spiralsFrom:[5,7],essentialQuestion:"How do I communicate a request so that another person has the information needed to act on it?",concepts:["Purpose and audience — a referral is read by someone with no knowledge of this patient","Required information: what the receiver must have before they can act","Concise requests — a request buried in narrative gets actioned last","Supporting information versus padding","Follow-up: a request with no tracking is a request that disappears","Documentation of communication — record that the request was made, when, and to whom"],grammar:[{heading:"Paragraph organization",points:["The topic sentence states the paragraph's point, usually first","Supporting details back it up, and each one earns its place","Logical order: the reader should never have to re-read to follow you","Transitions connect the sentences so the paragraph reads as one thought"]}],wordListNumber:8,practice:[{kind:"missing-info",title:"What is missing from this request?",instructions:"Read the referral request as the specialist's office would receive it. Check every required element that is not there.",sample:"Hi — we'd like to refer a patient to your office for the knee problem we discussed. She's been having trouble for a while now and our provider thinks she should be seen. Please let us know when you can fit her in. Thanks!",elements:[{id:"t8-e1",label:"Patient's full name and date of birth",present:!1,why:"Without an identifier the receiving office cannot open a record or match the referral to a person."},{id:"t8-e2",label:"Referring provider's name",present:!1,why:"The specialist needs to know who to send findings back to, and who authorized the referral."},{id:"t8-e3",label:"Reason for referral, stated specifically",present:!1,why:"'The knee problem we discussed' means nothing to an office that was not in the conversation."},{id:"t8-e4",label:"Relevant clinical history and duration",present:!1,why:"'Trouble for a while' gives the specialist no basis for triage. How long, and what has been tried?"},{id:"t8-e5",label:"Insurance information and authorization status",present:!1,why:"Many specialist visits require prior authorization. Omitting this guarantees a delay or a denied claim."},{id:"t8-e6",label:"Urgency or requested timeframe",present:!1,why:"'When you can fit her in' hands the triage decision to someone with no clinical information."},{id:"t8-e7",label:"Contact details for the referring office",present:!1,why:"If anything is unclear, the specialist's office needs a way to reach you quickly."},{id:"t8-e8",label:"A stated request",present:!0,why:"This one is present — the message does ask for an appointment. It is the only element that is."}]},{kind:"sequencer",title:"Order the request",instructions:"Arrange these into the order a busy reader can act on fastest.",items:[{id:"t8-q1",text:"State the request and who it concerns: referral for [patient name, DOB] to orthopedics.",position:1,reason:"The reader must know within one line what this is and who it is about, so they can route it before reading further."},{id:"t8-q2",text:"Give the reason for the referral, specifically.",position:2,reason:"The clinical reason determines who sees it and how urgently. It comes before the history that supports it."},{id:"t8-q3",text:"Supply the relevant history: duration, findings, and what has already been tried.",position:3,reason:"Supporting detail follows the point it supports. Leading with history buries the request."},{id:"t8-q4",text:"Provide insurance and authorization information.",position:4,reason:"Administrative detail comes after the clinical picture — necessary, but not what the reader needs first."},{id:"t8-q5",text:"State the requested timeframe and give your contact details.",position:5,reason:"The close tells the reader what you want and how to reach you if anything is missing."}]},{kind:"grammar-drill",title:"Topic sentences and transitions",instructions:"Paragraph organization — the grammar that makes a request readable.",items:[{id:"t8-g1",prompt:"Which sentence works best as the topic sentence of a referral paragraph?",principle:"A topic sentence states the paragraph's point. In a request, that means saying what you are asking for before you explain why.",choices:[{text:"Ms. Chen has been experiencing knee pain, and she also mentioned some difficulty sleeping, and her last visit was in March.",correct:!1,rationale:"Three unrelated facts and no point. The reader does not know what this paragraph is for."},{text:"We are requesting an orthopedic referral for Ms. Chen for right knee pain of four months' duration.",correct:!0,rationale:"Correct. States the request, the patient, the reason, and the duration in one sentence. Everything after it is support."},{text:"As you may know, knee pain is a common presenting complaint in primary care.",correct:!1,rationale:"General background that tells the reader nothing about this patient or this request."},{text:"Please see the attached.",correct:!1,rationale:"Makes the reader open a document before they know whether it is urgent or even theirs."}]},{id:"t8-g2",prompt:"Which transition correctly signals that the next sentence gives a result?",principle:"Transitions tell the reader how sentences relate. Using the wrong one sends them looking for a relationship that is not there.",choices:[{text:"However",correct:!1,rationale:"'However' signals contrast, not result."},{text:"Therefore",correct:!0,rationale:"Correct. 'Therefore' tells the reader that what follows is the consequence of what came before."},{text:"Similarly",correct:!1,rationale:"'Similarly' signals comparison between two like things."},{text:"Meanwhile",correct:!1,rationale:"'Meanwhile' signals simultaneous time, not consequence."}]},{id:"t8-g3",prompt:"A paragraph in your referral contains six sentences, one of which describes the patient's holiday plans. What should you do?",principle:"Every supporting detail must support the topic sentence. Detail that does not is padding, and padding is where the reader's attention goes to die.",choices:[{text:"Keep it — it gives the specialist a sense of the patient as a person",correct:!1,rationale:"The specialist needs clinical and administrative information. Personal detail that does not bear on care is a privacy question as well as a clarity one."},{text:"Remove it — it does not support the request, and it lengthens what a busy reader must get through",correct:!0,rationale:"Correct. If it does not help the reader act, it competes with what does. Minimum necessary applies to referrals too."},{text:"Move it to the end so it does not interrupt",correct:!1,rationale:"Moving irrelevant information does not make it relevant."},{text:"Put it in a separate paragraph",correct:!1,rationale:"Same problem, now with its own heading."}]}]},{kind:"builder",storageKey:"referral",title:"Build a referral request",instructions:"Write each part. The completeness check looks for the elements the receiving office cannot act without.",scenario:"Ms. Wen Chen, date of birth 4 March 1968, has had right knee pain for four months. It worsens on stairs and after standing for long periods. She has tried over-the-counter ibuprofen with partial relief. An X-ray taken last week showed changes consistent with osteoarthritis. Dr. Amara Reyes is referring her to orthopedics. Her insurance is Meridian Health, member number MH-4471902, and prior authorization has been obtained, reference PA-88213. Dr. Reyes would like her seen within four weeks. Your office number is 555-0134.",fields:[{id:"request",label:"The request",prompt:"One sentence: what you are asking for, for whom, and why. This is your topic sentence.",expects:["chen"],missingHint:"Name the patient — the receiving office cannot match a referral without an identifier.",rows:2},{id:"history",label:"Relevant history",prompt:"Duration, findings, and what has already been tried. Enough to triage, nothing more.",expects:["four months","4 months","x-ray","ibuprofen"],missingHint:"Include how long this has been going on and what has already been tried."},{id:"insurance",label:"Insurance and authorization",prompt:"Carrier, member number, and authorization reference if obtained.",expects:["meridian","mh-","pa-"],missingHint:"Include the carrier and the authorization reference, or the visit may be delayed or denied."},{id:"close",label:"Timeframe and contact",prompt:"When you would like the patient seen, and how to reach you.",expects:["four weeks","4 weeks","555"],missingHint:"State the requested timeframe and a contact number — otherwise triage and follow-up both stall.",rows:2}]},{kind:"word-bank",title:"Words to spell",listNumber:8}],product:{label:"Referral / prior authorization communication",description:"Produce a complete referral or prior authorization request from the case above. The receiving office should need to ask you nothing. Organize it in paragraphs with clear topic sentences."},reflection:["Read it as the specialist's scheduler. Could you book this patient without calling back?","Does each paragraph have one point, stated in its first sentence?","Is there anything here the receiving office does not need?"],beforeYouLeave:["Identified every missing element in the incomplete referral","Put the request into the order a busy reader can act on","Completed the topic sentence and transition drill","Built the referral and ran the completeness check"]},{number:9,slug:"9",title:"Professional Emails & Workplace Messages",unit:{number:4,title:"Workplace & Team Communication"},sessions:"2",goals:["professional-writing","grammar-sentence"],spiralsFrom:[2,6,7],essentialQuestion:"How do I write a message that is professional, clear, and appropriate for the workplace?",concepts:["Email structure: subject line, greeting, purpose, detail, action, closing","Subject lines that tell the reader what the message is and whether it needs them","Audience — a message to a supervisor, a coworker, and an outside office are three different messages","Tone that is direct but respectful; directness is not rudeness","Making requests and responding to them","Professional openings and closings, and when 'Hi' is fine"],grammar:[{heading:"Sentence variety and punctuation",points:["Commas that separate clauses, items in a series, and introductory phrases","Semicolons joining two complete sentences that belong together","Sentence combining — turning three short sentences into one that reads well","Fragments and run-ons, spiralling from Topics 2 and 6"]},{heading:"Parallel structure",points:["Items in a list take the same grammatical form","'Verify insurance, update the chart, and confirm the appointment' — three imperatives","Breaking parallelism makes a list read as though something is missing"]}],wordListNumber:9,practice:[{kind:"choose-best",title:"Subject-line challenge",scenario:"You need your supervisor to approve a schedule change for next Thursday so you can attend a required training. You need an answer before Wednesday.",instructions:"The subject line is the only part some readers will see before deciding when to open your message.",items:[{id:"t9-c1",prompt:"Which subject line should you use?",principle:"A subject line should say what the message is about and, when it matters, what is needed and by when. It is not a greeting.",choices:[{text:"Question",correct:!1,rationale:"Tells the reader nothing. In an inbox of forty messages this one gets opened last."},{text:"Hi!",correct:!1,rationale:"A greeting, not a subject. The greeting belongs in the first line of the message."},{text:"Schedule change request for Thurs 16 Oct — need approval by Wed",correct:!0,rationale:"Correct. Says what it is, which date it concerns, what is needed, and the deadline. The reader can triage it without opening it."},{text:"URGENT!! PLEASE READ ASAP!!!",correct:!1,rationale:"Shouting without information. It also spends credibility you will want later for something genuinely urgent."}]},{id:"t9-c2",prompt:"Your supervisor replies approving it. Which response is appropriate?",principle:"Close the loop briefly. A reply that confirms receipt and restates the outcome prevents a later disagreement about what was agreed.",choices:[{text:"(no reply)",correct:!1,rationale:"Leaves your supervisor unsure you saw it, and leaves no record that you understood the terms."},{text:"Thank you — confirming I will be off the floor Thursday 16 October from 1:00 to 4:00 for the training, and back for the afternoon clinic.",correct:!0,rationale:"Correct. Brief, restates the specifics so any misunderstanding surfaces now, and creates a record."},{text:"ok thx",correct:!1,rationale:"Confirms receipt and nothing else. It is also a register you would not use with a supervisor in person."},{text:"Thank you so much, I really appreciate you taking the time to consider this, it means a great deal and I am so grateful for your flexibility and support with this and everything else.",correct:!1,rationale:"Warm but disproportionate, and it omits the detail that makes the reply useful. Over-thanking reads as anxiety."}]}]},{kind:"rewrite",title:"Email repair bench",instructions:"Repair each part of a broken workplace email. Each fix demonstrates one principle.",items:[{id:"t9-r1",before:"Subject: (blank)",problem:"No subject line. The message cannot be triaged, found later, or filed.",model:"Subject: Supply order for Thursday — need item numbers by Tues 3pm",rubric:["States what the message is about","Includes the deadline where one exists","Short enough to read in an inbox list","Contains no all-caps or multiple exclamation marks"]},{id:"t9-r2",before:"hey so i need those numbers for the order, its kind of urgent, the order goes in thursday and i dont have the item codes from your side yet so can you send them",problem:"No greeting, no capitalization, run-on structure, missing apostrophes, and the actual request is buried at the end.",model:"Hi Marcus,\n\nCould you send me the item codes for Thursday's supply order? I have everything else ready and just need those to submit it.\n\nCould you get them to me by 3:00 p.m. Tuesday? That gives me time to check the order before it goes in.\n\nThanks,\nJ.",rubric:["Opens with a greeting and names the reader","States the request in the first sentence","Gives a specific deadline and a reason for it","Correct capitalization, apostrophes, and sentence breaks","Closes appropriately"]},{id:"t9-r3",before:"You need to verify the insurance, updating the chart, and then you should confirm the appointment.",problem:"The three items are not parallel — an imperative, a gerund, and a 'you should'. The list reads as though something is missing.",model:"Please verify the insurance, update the chart, and confirm the appointment.",rubric:["All three items take the same grammatical form","The list can be read as one instruction","No shift between 'you need to', 'you should', and imperatives","Reads naturally out loud"]}]},{kind:"grammar-drill",title:"Commas, semicolons, and combining",instructions:"The punctuation that makes a workplace message readable.",items:[{id:"t9-g1",prompt:"Which sentence uses the semicolon correctly?",principle:"A semicolon joins two complete sentences that are closely related. If either side could not stand alone, use a comma or a different construction.",choices:[{text:"The order goes in Thursday; please send the codes by Tuesday.",correct:!0,rationale:"Correct. Both sides are complete sentences and they belong together."},{text:"The order goes in Thursday; because I need the codes first.",correct:!1,rationale:"The second half is a fragment. A semicolon needs a complete sentence on both sides."},{text:"Please send; the item codes by Tuesday.",correct:!1,rationale:"This splits a single sentence in half."},{text:"The order goes in Thursday; and please send the codes.",correct:!1,rationale:"A semicolon and a coordinating conjunction do the same job. Use one or the other."}]},{id:"t9-g2",prompt:"Which sentence correctly punctuates the introductory phrase?",principle:"An introductory phrase is followed by a comma. Without it, the reader briefly attaches the phrase to the wrong thing.",choices:[{text:"After you verify the insurance please update the chart.",correct:!1,rationale:"Missing the comma after the introductory clause, which makes the reader stumble on 'insurance please'."},{text:"After you verify the insurance, please update the chart.",correct:!0,rationale:"Correct. The comma marks the end of the introductory clause."},{text:"After, you verify the insurance please update the chart.",correct:!1,rationale:"The comma is in the wrong place and breaks the clause."},{text:"After you verify, the insurance please update the chart.",correct:!1,rationale:"The comma splits the clause and changes the meaning."}]},{id:"t9-g3",prompt:"Which list is parallel?",principle:"Parallel structure means every item in a list takes the same grammatical form. It is one of the quickest ways to make writing sound competent.",choices:[{text:"Verify the insurance, updating the chart, and you should confirm the appointment.",correct:!1,rationale:"Imperative, gerund, then 'you should'. Three different forms in one list."},{text:"Verify the insurance, update the chart, and confirm the appointment.",correct:!0,rationale:"Correct. Three imperatives, same form throughout."},{text:"Verification of insurance, update the chart, and confirming the appointment.",correct:!1,rationale:"Noun phrase, imperative, gerund — not parallel."},{text:"You need to verify the insurance, the chart needs updating, and confirm the appointment.",correct:!1,rationale:"Three different constructions, and the second one loses the doer entirely."}]},{id:"t9-g4",prompt:"Which is the best way to combine: 'The order goes in Thursday. I need the item codes. Please send them by Tuesday.'",principle:"Combining sentences shows the relationship between ideas. Three short sentences in a row read as choppy and make the reader work out the connection.",choices:[{text:"The order goes in Thursday, I need the item codes, please send them by Tuesday.",correct:!1,rationale:"Three complete sentences spliced with commas — a run-on."},{text:"The order goes in Thursday, so please send me the item codes by Tuesday.",correct:!0,rationale:"Correct. Combines cause and request into one sentence, and 'so' makes the relationship explicit."},{text:"The order goes in Thursday and I need the item codes and please send them by Tuesday.",correct:!1,rationale:"Strung together with 'and'; the relationship between the parts is lost."},{text:"Thursday order; item codes; Tuesday.",correct:!1,rationale:"Compressed into fragments. Brevity that costs the reader comprehension is not an improvement."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:9}],product:{label:"Professional email",description:"Write a complete professional email to a supervisor or coworker from the scenario below: subject line, greeting, the request in the first sentence, the detail that supports it, a specific deadline, and a closing. Keep it under 120 words.",scenario:"You are the assistant responsible for Thursday's supply order. You still need item codes from the clinical lead, Marcus, and you need them by Tuesday afternoon to check the order before it submits. Marcus has been covering two units this week and is behind on email."},reflection:["Read only your subject line. Would you know when to open this message?","Is the request in the first sentence, or did you build up to it?","Are your lists parallel? Read them out loud — the ear catches it faster than the eye."],beforeYouLeave:["Completed the subject-line challenge","Repaired all three parts of the broken email","Completed the punctuation and parallelism drill","Drafted the email and checked it against the Communication Check"]},{number:10,slug:"10",title:"Proofreading, Revision & AI as a Writing Coach",unit:{number:5,title:"Revision, AI & Integrated Communication"},sessions:"2",goals:["grammar-sentence","professional-writing","documentation"],spiralsFrom:[2,3,4,6,9],essentialQuestion:"How can I use AI to improve my writing without allowing AI to take responsibility for my work?",concepts:["Revising versus proofreading — revising changes what the writing says; proofreading fixes how it is written. Do them in that order.","AI as a writing coach: what it is good at, and what it cannot do","Prompting for feedback rather than for a rewrite","Checking AI suggestions instead of accepting them","Hallucination — AI invents facts, citations, and details with complete confidence","Privacy and HIPAA: patient information must never be entered into an AI tool","You remain responsible for the final content, whatever produced the draft"],grammar:[{heading:"Spiraling error checklist",points:["Agreements: subject–verb, and pronoun–antecedent","Fragments and run-ons","Punctuation and capitalization","Word choice — the confusable pairs from every earlier list"]}],wordListNumber:{note:"The Instructor's Guide lists no new spelling words for Topic 10. The Word Bank below offers spiral review of Lists 1–9 instead. Confirm whether a Topic 10 list should be added, or whether spiral review is the intent."},practice:[{kind:"error-hunt",title:"Error hunt",instructions:"This message is going to a patient. Find every error before it does.",paragraph:"Dear Ms. Alvarez, Thank you for you're call yesterday. The results of your test is back and Dr. Reyes would like to discuss it with you. Because we could not reach you by phone. Please call our office at 555-0134 on wendsday between 9am and 4pm, we can also reschedule your appointment at that time if needed. The list of things to bring are on the back of this letter. Sincerely, the office team",spans:[{text:"you're call",category:"Word choice",correction:"your call — 'you're' means 'you are'"},{text:"is back",category:"Subject–verb agreement",correction:"are back — the subject is 'results', which is plural"},{text:"Because we could not reach you by phone.",category:"Fragment",correction:"Join it to the next sentence: 'Because we could not reach you by phone, please call our office…'"},{text:"wendsday",category:"Spelling and capitalization",correction:"Wednesday — silent 'd', and days of the week are capitalized"},{text:"4pm, we can also",category:"Run-on",correction:"4 p.m. We can also — two complete sentences need a period"},{text:"list of things to bring are",category:"Subject–verb agreement",correction:"list … is — the subject is 'list', which is singular"},{text:"the office team",category:"Capitalization",correction:"The Office Team — a closing signature is capitalized"}]},{kind:"grammar-drill",title:"Human editing versus AI editing",instructions:"Where each one helps, and where each one fails.",items:[{id:"t10-g1",prompt:"Which task is AI genuinely good at, in a way you can rely on?",principle:"AI is strong on the surface features of language and unreliable on facts. Use it where a mistake would be visible to you.",choices:[{text:"Confirming that a medication dosage in your draft is correct",correct:!1,rationale:"Never. AI generates plausible numbers and states them confidently. Clinical facts come from clinical sources."},{text:"Pointing out that a sentence is unclear or that a paragraph has no topic sentence",correct:!0,rationale:"Correct. This is a judgment about language, which you can then check yourself by rereading the sentence."},{text:"Deciding whether a patient's symptoms warrant an urgent appointment",correct:!1,rationale:"That is triage — a clinical judgment, and outside your scope as well as the tool's."},{text:"Supplying the citation for a clinical guideline you half-remember",correct:!1,rationale:"AI fabricates citations that look completely real. Find the actual source."}]},{id:"t10-g2",prompt:"Which prompt asks AI for coaching rather than for a replacement?",principle:"A prompt that asks for a rewrite gets you someone else's writing. A prompt that asks what is wrong gets you something to learn from.",choices:[{text:"Rewrite this to sound more professional.",correct:!1,rationale:"You get a new draft you did not write and cannot fully defend. You also learn nothing about what was wrong."},{text:"Identify anything unclear in this message, explain why each one is unclear, and do not rewrite it.",correct:!0,rationale:"Correct. Asks for diagnosis with reasoning, and explicitly withholds the rewrite so the revision stays yours."},{text:"Make this better.",correct:!1,rationale:"Vague, and it hands over the whole task."},{text:"Write me a patient instruction sheet about wound care.",correct:!1,rationale:"This is not editing at all — and an AI-written clinical instruction sheet is exactly the thing nobody should distribute unchecked."}]},{id:"t10-g3",prompt:"You want AI feedback on a message you wrote about a specific patient. What must you do first?",principle:"Anything you paste into an AI tool leaves your organization. Protected health information cannot go into a consumer tool under any circumstances.",choices:[{text:"Paste it as-is — the tool is private to your account",correct:!1,rationale:"An account is not a business associate agreement. This is a disclosure of PHI to a third party, and it is reportable."},{text:"Remove every identifier first, or ask about the general situation without the specifics",correct:!0,rationale:"Correct. The tool can help with tone and structure without knowing anything about a real person. Strip the identifiers, or ask generically."},{text:"Change only the patient's name",correct:!1,rationale:"Date of birth, dates of service, and condition are identifiers too. Partial redaction is not de-identification."},{text:"Paste it and delete the conversation afterwards",correct:!1,rationale:"Deleting your view of a conversation does not undo the transmission or guarantee deletion from the provider's systems."}]},{id:"t10-g4",prompt:"Revising and proofreading — which order, and why?",principle:"Proofreading polishes sentences. Revising may delete them. Polishing first wastes the work.",choices:[{text:"Proofread first, then revise",correct:!1,rationale:"You will spend time perfecting the punctuation of sentences you are about to cut."},{text:"Revise first, then proofread",correct:!0,rationale:"Correct. Settle what the writing says and how it is organized, then fix the surface of what survived."},{text:"They are the same thing",correct:!1,rationale:"Revising changes content and structure; proofreading fixes grammar, spelling, and punctuation."},{text:"Do both at once to save time",correct:!1,rationale:"Trying to do both means doing neither well — you lose the thread of the argument while hunting commas."}]}]},{kind:"ai-lab",title:"AI feedback lab",instructions:"The full chain: your original, the AI's feedback, your evaluation of that feedback, and your revision. Panel 3 is the one that matters.",starter:"Dear Mr. Osei,\n\nYour appointment is coming up soon. Please make sure you don't eat anything beforehand and bring all your stuff. If you have any issues just let us know. We look forward to seeing you.\n\nThanks,\nThe Office",badRevision:{text:"Dear Mr. Osei,\n\nYour appointment is scheduled for Tuesday, 21 October at 8:30 a.m. Please fast for a minimum of 12 hours beforehand, and bring your insurance card, photo ID, and a complete list of your current medications including dosages. Per CDC guideline 2019-A, patients over 60 should also discontinue anticoagulant therapy 48 hours prior.\n\nWarm regards,\nThe Office Team",problems:["The date and time were invented — the original message never gave them.","The 12-hour fasting requirement was invented; the original did not specify a duration.",'"CDC guideline 2019-A" does not exist. AI fabricates citations that look completely real.',"It gives clinical advice about stopping anticoagulant therapy — dangerous, and far outside an administrative writer's scope.","The specific detail makes it read as more authoritative than the original, which is exactly why an unchecked version would go out."]}},{kind:"word-bank",title:"Spiral review — Lists 1 to 9",listNumber:9}],product:{label:"Revised healthcare communication",description:"Take one piece of healthcare writing you produced earlier in this course and produce the full chain: the original, the AI feedback you received, your written evaluation of that feedback, and your revised final version. Submit all four parts. The evaluation is what is being assessed — it is the part only you can write."},reflection:["Which AI suggestions did you reject, and could you defend each rejection?","Did the AI change anything factual? Did you check it?","Is your revision better, or just different?"],beforeYouLeave:["Found every error in the error hunt","Completed the human-versus-AI editing drill","Completed all four panels of the AI feedback lab","Identified every problem in the bad AI revision","Submitted the four-part revision chain"],closingLine:"AI can suggest. You decide."}],f=[...e,...d];function g(a){return f.find(b=>b.number===a)}function h(a){let b=a>=101?d:e,c=b.findIndex(b=>b.number===a);return{previous:c>0?b[c-1]:void 0,next:c>=0&&c<b.length-1?b[c+1]:void 0}}let i=[{unit:1,unitTitle:"Foundations of Professional Healthcare Communication",number:1,title:"Course Introduction: Building Our Class Community",sessions:"1",product:"Professional self-introduction (writing warm-up)",built:!0},{unit:1,unitTitle:"Foundations of Professional Healthcare Communication",number:2,title:"Foundations: Clear and Professional Communication",sessions:"1–2",product:"Professional patient/staff communication",built:!0},{unit:2,unitTitle:"Clinical Documentation",number:3,title:"Writing About Patients: Objective Documentation",sessions:"2",product:"Brief patient encounter note",built:!0},{unit:2,unitTitle:"Clinical Documentation",number:4,title:"SOAP Notes: Organizing Clinical Information",sessions:"1",product:"Basic SOAP note",built:!0},{unit:2,unitTitle:"Clinical Documentation",number:5,title:"Handoffs, Messages & Professional Communication",sessions:"1",product:"Written handoff / SBAR message",built:!0},{unit:3,unitTitle:"Patient Communication",number:6,title:"Writing Clear Patient Instructions",sessions:"2",product:"Patient instruction sheet",built:!0},{unit:3,unitTitle:"Patient Communication",number:7,title:"Patient Messages, Reminders & Follow-Up",sessions:"1–2",product:"Patient portal message or reminder",built:!0},{unit:3,unitTitle:"Patient Communication",number:8,title:"Referrals, Prior Authorizations & Requests",sessions:"1–2",product:"Referral / prior authorization communication",built:!0},{unit:4,unitTitle:"Workplace & Team Communication",number:9,title:"Professional Emails & Workplace Messages",sessions:"2",product:"Professional email",built:!0},{unit:5,unitTitle:"Revision, AI & Integrated Communication",number:10,title:"Proofreading, Revision & AI as a Writing Coach",sessions:"2",product:"Revised healthcare communication",built:!0},{unit:6,unitTitle:"Final",number:"final",title:"Integrated Healthcare Communication & Grammar",sessions:"1",product:"3–4 original writings from one case + grammar/spelling quiz",built:!0}]}};